#include <Arduino.h>

struct LcdGlyph {
  uint16_t code;
  uint16_t offset;
  uint8_t width;
  uint8_t height;
  int8_t xOffset;
  int8_t yOffset;
  uint8_t xAdvance;
};

struct LcdFont {
  const LcdGlyph* glyphs;
  const uint8_t* bitmap;
  uint16_t glyphCount;
  uint8_t lineHeight;
  uint8_t baseline;
};

